<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\MedicalRecord; use Illuminate\Http\Request;
class MedicalRecordController extends Controller { public function index(){return view('admin.healthcare.index',['records'=>MedicalRecord::with('child')->latest('record_date')->paginate(20)]);} public function store(Request $r){$d=$r->validate(['child_id'=>'required|exists:children,id','record_date'=>'required|date','record_type'=>'required|max:120','notes'=>'nullable','expense'=>'nullable|numeric|min:0']);MedicalRecord::create($d);return back()->with('success','Restricted healthcare record saved.');} public function update(Request $r,MedicalRecord $record){$d=$r->validate(['record_date'=>'required|date','record_type'=>'required|max:120','notes'=>'nullable','expense'=>'nullable|numeric|min:0']);$record->update($d);return back()->with('success','Healthcare record updated.');} public function destroy(MedicalRecord $record){$record->delete();return back()->with('success','Healthcare record deleted.');} }
